-- Migration: create paaas_2026 table + import Programa Anual de Adquisiciones,
-- Arrendamientos y Servicios (PAAAS) 2026 catalog verbatim from data/PAAAS_2026.csv.
-- Folio del documento: 1875315554. 462 registros: 75 partidas independientes,
-- 15 grupos de adquisición consolidada (tipo_registro='grupo') y 372 sub-partidas
-- ligadas a su grupo via grupo_id (auto-referencia a esta misma tabla).

CREATE TABLE IF NOT EXISTS public.paaas_2026 (
  id                            SERIAL PRIMARY KEY,
  tipo_registro                 TEXT NOT NULL CHECK (tipo_registro IN ('independiente','grupo','subpartida')),
  grupo_id                      INTEGER REFERENCES public.paaas_2026(id),
  cucop                         TEXT,
  concepto                      TEXT NOT NULL,
  valor_total_estimado_compra   NUMERIC(18,2),
  valor_estimado_compras_mipymes NUMERIC(18,2),
  cantidad                      NUMERIC(14,2),
  unidad_medida                 INTEGER,
  entidad_federativa            INTEGER,
  t1                            NUMERIC(18,2),
  t2                            NUMERIC(18,2),
  t3                            NUMERIC(18,2),
  t4                            NUMERIC(18,2),
  fecha_estimada_procedimiento  TEXT,
  plurianualidad                INTEGER,
  ejercicios_fiscales           INTEGER,
  monto_ejercer_presente_anio   NUMERIC(18,2),
  comentario_1                  TEXT,
  comentario_2                  TEXT,
  comentario_3                  TEXT,
  created_at                    TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_paaas_2026_grupo_id ON public.paaas_2026(grupo_id);
CREATE INDEX IF NOT EXISTS idx_paaas_2026_tipo_registro ON public.paaas_2026(tipo_registro);

ALTER TABLE public.paaas_2026 ENABLE ROW LEVEL SECURITY;

-- Lectura pública: paaas_2026 vive en el proyecto Supabase de AIFA-OPERACIONES
-- y se consulta desde la app de AIFA-Contratos con un cliente anónimo (sin
-- sesión de auth en este proyecto). Es un documento público de adquisiciones,
-- por lo que no hay dato sensible que proteger en la lectura.
DROP POLICY IF EXISTS "Authenticated users can read paaas_2026" ON public.paaas_2026;
DROP POLICY IF EXISTS "Public can read paaas_2026" ON public.paaas_2026;
CREATE POLICY "Public can read paaas_2026"
  ON public.paaas_2026 FOR SELECT
  USING (true);

-- Edición desde la app de Contratos (tabla con celdas editables en pantalla).
-- Igual que en la lectura, este cliente nunca lleva sesión contra este
-- proyecto, así que auth.role() = 'authenticated' nunca se cumpliría; quién
-- puede editar se controla del lado de la app (solo rol Administrador ve las
-- celdas como editables). No hay pantalla de alta/baja de partidas, así que
-- INSERT y DELETE se dejan cerrados.
DROP POLICY IF EXISTS "Authenticated users can update paaas_2026" ON public.paaas_2026;
DROP POLICY IF EXISTS "Public can update paaas_2026" ON public.paaas_2026;
CREATE POLICY "Public can update paaas_2026"
  ON public.paaas_2026 FOR UPDATE
  USING (true)
  WITH CHECK (true);

TRUNCATE public.paaas_2026;







